{ r5=add(r5,mpyi(r12,#16)); if(p3) r10=add(r0,#0); if(!p3) r10=add(r1,#0) }
{ p0=cmp.eq(r4,#8); if(p0.new) r10=add(r10,#32); if(p0.new) r5=add(r5,#4) }
{ r10=insert(r13,#1,#0) }
{ nop } // typed R1=ictagr(R10)
{ p0=tstbit(r1,#1); if(!p0.new) jump:nt finish_inner; memw(r14+r5<<#0)=r1 }
{ r0=insert(r1,#19,#5); r5=#0 }
{ r5=asl(r12,#7); if(p3) r3=add(r0,#0); r0=#0 }
{ r0=insert(r1,#18,#6); r1=#0 }
{ r5=add(r5,mpyi(r13,##64)); if(!p3) r3=add(r0,#0); r0=#0 }
